// Get the accumulated file size in bytes of all the resources a scene has used
void EditorPackedScenePreviewPlugin::_get_scene_file_sizes(const String &p_path, HashMap<String, uint64_t> &r_sizes) const {
	// Record file size
	if (!r_sizes.has(p_path)) {
		r_sizes[p_path] = FileAccess::get_size(p_path);
	}

	// Is regular resource file
	if (!p_path.has_extension("tscn") && !p_path.has_extension("scn")) {
		return;
	}

	// Is scene file, find resource dependencies
	List<String> dependencies;
	ResourceLoader::get_dependencies(p_path, &dependencies);

	for (String &dep : dependencies) {
		const PackedStringArray uid_res = dep.split("::::"); // uid::::res
		if (uid_res.size() < 2) {
			continue;
		}
		String file_path = uid_res[1];
		_get_scene_file_sizes(file_path, r_sizes);
	}
}
